REPLACE INTO `rune_template_locale` (`rune_id`, `locale`, `name`, `description`) VALUES
(7001002, 'esES', 'Frenesí sangriento', 'Ahora, Desgarrar se puede usar en actitud rabiosa. El daño de Desgarrar aumenta un $s2% y la facultad inflige una cantidad de daño adicional equivalente a un $s3% de tu poder de ataque cada vez que inflige daño.'),
(7001003, 'esES', 'Flagelación', 'Obtienes ira del daño físico recibido como si no llevases armadura.'),
(7001004, 'esES', 'Arremetida enfurecida', 'Un golpe feroz que inflige un $s1% de daño con arma, pero solo se puede usar si Enfurecer, Ira rabiosa o Ira sangrienta están activos. Al usar el resto de facultades cuerpo a cuerpo cuando Enfurecer, Ira rabiosa o Ira sangrienta están activos reducirá $s3 s el tiempo de reutilización restante de Arremetida enfurecida.'),
(7001005, 'esES', 'Belisario', 'Tus facultades Cargar, Interceptar e Intervenir ahora se pueden usar en combate y en cualquier actitud. Además, eliminarán todos los efectos de reducción de movimiento al activarse.'),
(7001006, 'esES', 'Grito de orden', 'El guerrero grita y aumenta $s1 p. el aguante de los miembros del grupo en un radio de $a1 m. Dura $d.'),
(7001007, 'esES', 'Consumido por la ira', 'Te enfurece durante 12 s después de superar los 60 de ira, lo que permite usar facultades que requieren estar enfurecido. Además, mientras estás enfurecido, Torbellino también golpea con el arma de mano izquierda.'),
(7001008, 'esES', 'Asalto frenético', 'Mientras empuñas armas a dos manos, tu velocidad de ataque aumenta un $s1% y tus golpes cuerpo a cuerpo certeros generan $s2 de ira adicional, o ${$m2*2} de ira adicional si son críticos.'),
(7001009, 'esES', 'Trueno de furia', 'Ahora Atronar aumenta el tiempo entre ataques un 6% adicional, se puede usar en cualquier actitud e inflige un 100% más de daño.'),
(7001010, 'esES', 'Gancho', 'Lanza una cadena con gancho que restringe al objetivo y lo arrastra hacia ti. No se puede usar contra enemigos de más de un nivel por encima del tuyo ni que estén marcados como jefes.'),
(7001011, 'esES', 'Golpe rápido', 'Un ataque cuerpo a cuerpo instantáneo e imprudente con tu arma a dos manos que inflige daño según tu poder de ataque. Esta facultad se beneficia de, y activa, todos los efectos asociados a Golpe heroico.'),
(7001012, 'esES', 'Furia enfocada', 'Con la doble empuñadura, tu velocidad de movimiento aumenta un 10% y obtienes un 4% de velocidad de ataque cada vez que tus ataques automáticos cuerpo a cuerpo golpean al mismo objetivo que tu ataque automático anterior. Se acumula hasta 5 veces. Dura 10 s o hasta que tus ataques automáticos golpean a otro objetivo.'),
(7001013, 'esES', 'Ataque de la victoria', 'Ataca al objetivo de manera instantánea y le inflige ${1+$AP*$m3/100} p. de daño, además de sanarte un $s2% de tu salud máxima. Solo se puede usar en $32216d después de haber matado a un enemigo que otorgue experiencia u honor.'),
(7001014, 'esES', 'Oleada sangrienta', 'Golpe heroico, Sed de sangre y Torbellino tienen un $h% de probabilidad de hacer que tu siguiente Embate en $413399d sea instantáneo y no cueste ira.'),
(7001015, 'esES', 'Ira enfocada', 'Reduce el coste de ira de tus facultades ofensivas $/10;s1 p.'),
(7001016, 'esES', 'Sincronización precisa', 'Ahora, Embate es instantáneo, pero tiene un tiempo de reutilización de ${$m2/1000} s.'),
(7001017, 'esES', 'Regeneración iracunda', 'Te sana un $o1% de tu salud máxima durante $d, pero solo se puede usar si Enfurecer, Ira rabiosa o Ira sangrienta están activos. Se puede usar mientras estás aturdido.'),
(7001018, 'esES', 'Actitud de gladiador', 'Una actitud agresiva: mientras llevas un escudo aumenta un 10% tu daño y un 10% tu probabilidad de bloqueo, pero reduce un 30% tu armadura y un 30% la amenaza que generas. Con un escudo durante Actitud de gladiador puedes usar todas las facultades restringidas a otras actitudes.'),
(7001019, 'esES', 'Intervenir', 'Corres a gran velocidad hacia un miembro del grupo e interceptas el siguiente ataque cuerpo a cuerpo o a distancia que le hagan, además de reducir su amenaza total.'),
(7001020, 'esES', 'Berrido de convocación', 'Sueltas un berrido de convocación que otorga a todos los miembros del grupo y la banda que se encuentren en un radio de 40 m un $s1% más de salud máxima durante $d.'),
(7001021, 'esES', 'Ira interminable', 'Generas un $s1% más de ira con todo el daño que infliges.'),
(7001022, 'esES', 'Maestría con escudos', 'Aumenta un 9% todo el daño físico que infliges mientras llevas un escudo y reduce un 51% la duración de todos los efectos de desarme que se usan contra ti. No se acumula con otros efectos de reducción de la duración de desarme.'),
(7001023, 'esES', 'Gusto por la sangre', 'Cada vez que tu facultad Desgarrar inflige daño, tu facultad Abrumar se activa durante $426969d o hasta el siguiente ataque. Este efecto no podrá ocurrir más de una vez cada $s1 s.'),
(7001024, 'esES', 'Vigilancia', 'Enfoca tu mirada protectora sobre un objetivo de grupo o banda, reduce un $s1% el daño que recibe y te transfiere un $m2% de la amenaza que genera. Además, cada vez que recibe un impacto de un ataque, tu tiempo de reutilización de Provocar se reinicia. Dura $d. Este efecto solo puede estar activo sobre un objetivo cada vez.'),
(7001025, 'esES', 'Desenfreno', 'Te vuelves loco, lo que aumenta un $s1% tu poder de ataque durante $d. Esta facultad solo se puede usar mientras estás enfurecido.'),
(7001026, 'esES', 'Escudo y espada', 'Cuando tus facultades Devastar o Revancha infligen daño, tienen un $h% de probabilidad de reiniciar el tiempo de reutilización de Embate con escudo y reducir un $426979s1% durante $426979d su coste de ira.'),
(7001027, 'esES', 'Equipo de demolición', 'Tus golpes críticos cuerpo a cuerpo te enfurecen (lo que activa las facultades que requieren este estado), y aumenta un $427066s1% el daño de Golpe mortal, Sed de sangre y Embate con escudo durante $427066d.'),
(7001028, 'esES', 'Carne fresca', 'La primera vez que infliges daño a un objetivo con Sed de sangre, Golpe mortal o Embate con escudo, tienes un 100% de probabilidades de enfurecerte (lo que activa las facultades que requieran dicho estado) y, con cada ataque posterior, tienes un $s2% de probabilidades. Al enfurecerte, infliges un $440483s1% más de daño físico durante $440483d.'),
(7001029, 'esES', 'Ola de choque', 'Lanza una ola de fuerza delante del guerrero, inflige ${$m3/100*$AP} p. de daño y aturde a todos los objetivos cercanos que se encuentren en un radio de $a1 m en un cono frontal durante $d.'),
(7001030, 'esES', 'Muerte súbita', 'Tus golpes cuerpo a cuerpo tienen un $h% de probabilidades de otorgar Muerte súbita. Muerte súbita permite usar Ejecutar con independencia de la salud del objetivo. Cuando Ejecutar se activa con Muerte súbita, conservas $s2 p. de ira tras usarla.'),
(7002011, 'esES', 'Infusión de Luz', 'Aumenta un $s1% el daño y la sanación realizados con Choque Sagrado, reduce a 6 s el tiempo de reutilización de Choque Sagrado, y tus golpes críticos con Choque Sagrado devuelven su coste de maná y reducen $s3 s su tiempo de reutilización restante.'),
(7002012, 'esES', 'Gracia de Luz', 'Lanzar Luz Sagrada reduce 0,5 s el tiempo de lanzamiento de tu siguiente Luz Sagrada. Dura 15 s.'),
(7002013, 'esES', 'Salvaguardia mejorada', 'Aumenta un $s1% el daño evitado por tu Bendición de santuario y aumenta el daño infligido por tu Bendición de santuario el equivalente a un $s2% del valor de bloqueo de tu escudo.'),
(7002014, 'esES', 'Égida', 'Aumenta un $s2% tu valor de bloqueo y modifica tu talento Baluarte. Ahora, Baluarte tiene un $s1% de probabilidades de activarse con cualquier ataque a distancia o cuerpo a cuerpo que recibes y siempre se activa cuando asestas un golpe crítico cuerpo a cuerpo. Además, por cada punto de talento, tu talento Expiación obtiene un $s3% de probabilidades de activarse cuando recibes un ataque a distancia o cuerpo a cuerpo.'),
(7002015, 'esES', 'Vaina de Luz', 'Al infligir daño con tu arma cuerpo a cuerpo, tu daño con hechizos aumenta una cantidad equivalente al $s1% de tu poder de ataque durante $426159d.'),
(7002016, 'esES', 'Custodiado por la Luz', 'Cada vez que golpeas a un objetivo con tu arma cuerpo a cuerpo, ganas un $415058m1% de tu maná máximo cada $415058t1 s durante $415058d, pero la cantidad sanada por tus hechizos de sanación se reduce un $415058s2% mientras dura esta regeneración de maná.'),
(7002017, 'esES', 'Conmoción y terror', 'Mientras Furia justa no esté activa, al infligir daño con Choque Sagrado obtienes un daño con hechizos equivalente al $s1% de tu intelecto y reduces la amenaza que generas un $462832s2% durante $462832d.'),
(7002018, 'esES', 'Suelo sacralizado', 'Tu Consagración también sana a los miembros del grupo que están dentro de su zona un $s1% del daño de Consagración.'),
(7002019, 'esES', 'Señal de la Luz', 'El objetivo se convierte en una Señal de la Luz para los miembros de tu grupo o banda en un radio de 40 m. La sanación que lances sobre los miembros de tu grupo o banda también sanará a la señal un 75% de la cantidad sanada. Solo un objetivo puede ser la Señal de la Luz cada vez. Dura $d.'),
(7002020, 'esES', 'Martillo del honrado', 'Da un martillazo al objetivo actual y hasta a 2 objetivos cercanos más, e inflige cuatro veces el daño por segundo de tu mano derecha como daño Sagrado.'),
(7002021, 'esES', 'Escudo de rectitud', 'Embistes al objetivo con tu escudo e infliges daño Sagrado basado en tu valor de bloqueo más 179 p.'),
(7002022, 'esES', 'Luz divina', 'Sana a un objetivo amistoso entre $m1 y $M1 p. Un $s2% de cualquier exceso de sanación se convierte en un escudo de absorción que dura $458857d. Varios lanzamientos no acumulan este escudo. Se beneficia de todos los talentos y efectos que se activan con Luz Sagrada o la modifican.'),
(7002023, 'esES', 'Reprimenda', 'Interrumpe el lanzamiento de hechizos e impide lanzar hechizos de esa misma escuela durante 3 s.'),
(7002024, 'esES', 'Escudo sacro', 'Cada vez que el objetivo recibe daño, obtiene un escudo que absorbe daño y aumenta un 50% la probabilidad del paladín de asestar un golpe crítico con Destello de Luz durante un máximo de 6 s. Destello de Luz también sana al objetivo protegido un 100% extra durante 12 s. No puede obtener este efecto más de una vez cada 5 s. Dura 1 min. Solo un objetivo.'),
(7002025, 'esES', 'Inspiración ejemplar', 'Tu presencia inspiradora disipa periódicamente los efectos de miedo y sueño que afectan a miembros del grupo cercanos.'),
(7002026, 'esES', 'Mano de expiación', 'Mientras Furia recta está activa, aumenta la amenaza Sagrada hasta un 80%, las sanaciones de otros objetivos amistosos restauran un 25% de maná y reduce un 20% el daño que te dejaría por debajo del 35% de salud.'),
(7002027, 'esES', 'Protección maleable', 'Ahora puedes actuar durante Protección divina y su duración aumenta un 50%, pero solo reduce un 50% el daño que recibes en lugar de volverte inmune. Además, activar Escudo sagrado también te otorga 4 p. de poder de ataque por cada punto de habilidad de defensa que supere 5 veces tu nivel durante 15 s.'),
(7003003, 'esES', 'Disparo explosivo', ''),
(7003004, 'esES', 'Maestría en bestias', 'El daño y la salud de tu mascota aumentan un $s1% y su regeneración de enfoque aumenta un $s3%. Además, el Bramido de tu mascota también provoca al objetivo para que la ataque durante $409372d.'),
(7003005, 'esES', 'Golpes de cobra', 'Tus golpes críticos con facultades de disparo, de ataque y con Mordedura de mangosta hacen que los siguientes 2 ataques especiales de tu mascota asesten un golpe crítico.'),
(7003006, 'esES', 'Lobo solitario', 'Infliges un $s1% más de daño con todos tus ataques cuando no tienes una mascota activa.'),
(7003007, 'esES', 'Golpe de flanco', 'Tu mascota y tú infligís simultáneamente un $s2% de daño cuerpo a cuerpo. Después infliges un $s3% más de daño durante $d. Se acumula hasta $u veces. Los ataques básicos de tu mascota tienen un $s4% de probabilidades de restablecer el tiempo de reutilización de Golpe de flanco.'),
(7003008, 'esES', 'Disparo mortal', 'Intentas darle el golpe de gracia a un objetivo herido con un ataque a distancia que inflige un $s2% de daño con arma más ${$m1/100*$m2/100*$<damagepower>} p. Disparo mortal no tiene alcance mínimo. El tiempo de reutilización de Disparo mortal se restablece si se usa contra un enemigo que tiene un 20% de salud o menos.'),
(7003009, 'esES', 'Propagar serpientes', 'Los objetivos golpeados por tu Multidisparo también se ven afectados por tu Picadura de serpiente.'),
(7003010, 'esES', 'Instrucción de francotirador', 'Tus facultades de disparo tienen un $415401s1% más de probabilidad de golpe crítico si no te has movido durante $s1 s. Se acumula cada segundo hasta un máximo de $415401u veces. Con el máximo de acumulaciones, tu Disparo de puntería se vuelve instantáneo. Si te mueves, perderás 1 acumulación cada segundo.'),
(7003011, 'esES', 'Trinchar', 'Un ataque de barrido que golpea a todos los enemigos situados frente a ti con tus armas cuerpo a cuerpo e inflige un $s2% de daño con arma. Tu objetivo principal recibe un $s3% más de daño.'),
(7003012, 'esES', 'Destripacobras', 'Ahora Mordedura de mangosta tiene un $s3% de probabilidades de activarse con cada uno de tus ataques cuerpo a cuerpo, que pasa a ser de un 100% cuando el enemigo esquiva un ataque. Esta probabilidad se acumula y el porcentaje aumenta un $s3% con cada ataque si no se reinicia. Mordedura de mangosta también inflige una cantidad de daño extra equivalente a un $s2% de tu poder de ataque.'),
(7003013, 'esES', 'Aspecto de la víbora', 'El cazador asume el aspecto de la víbora, lo que hace que los ataques cuerpo a cuerpo y a distancia automáticos regeneren maná, pero reduce el daño total que inflige en $s2%. Además, obtiene un $s1% del maná máximo cada $t s. El maná ganado se basa en la velocidad de su arma. Solo puede haber 1 aspecto activo cada vez.'),
(7003014, 'esES', 'Debilidad expuesta', 'Tus golpes críticos cuerpo a cuerpo y a distancia aumentan tu poder de ataque un $409507s1% de tu agilidad actual durante $409507d.'),
(7003015, 'esES', 'Especialista en combate cuerpo a cuerpo', 'Golpe de raptor se lanza al instante, y Mordedura de mangosta y Golpe de raptor tienen un $s3% de probabilidad con cada ataque de restablecer el tiempo de reutilización de ambas facultades.'),
(7003016, 'esES', 'Disparo firme', 'Un disparo firme que inflige un $s2% de daño con arma a distancia.'),
(7003017, 'esES', 'Especialización en doble empuñadura', 'Aumenta un $s1% el daño de tu arma de mano izquierda y hace que Golpe de raptor golpee con ambas armas cuando llevas dos armas.'),
(7003018, 'esES', 'Lanzador de trampas', 'Ahora puedes colocar tus trampas congelantes, de inmolación y explosivas en cualquier ubicación dentro del alcance del Lanzador de trampas. Además, tus trampas de Fuego y de Escarcha comparten tiempos de reutilización distintos.'),
(7003019, 'esES', 'Golpe de dracoleón', 'Reemplaza Picadura de dracoleón con Golpe de dracoleón, un golpe feroz que inflige daño con arma y hace que el objetivo sangre y reciba daño en el tiempo. Requiere el talento Picadura de dracoleón.'),
(7003020, 'esES', 'Reflejos felinos', 'Aumenta un $s1% tu probabilidad de esquivar y un $s2% la de tu mascota. Además, reduce un $s3% el tiempo de reutilización de Golpe de flanco.'),
(7003021, 'esES', 'Bloquear y cargar', 'Cada vez que colocas una trampa, tu siguiente facultad de Disparo, excepto Disparo de dispersión, no cuesta maná ni tiene tiempo de reutilización.'),
(7003022, 'esES', 'Matanza rápida', 'Reduce un $s1% el tiempo de reutilización de Fuego rápido. Fuego rápido otorga un $s3% más de velocidad de ataque cuerpo a cuerpo, y tu siguiente facultad de Disparo después de matar a un objetivo que otorgue experiencia u honor inflige un $415407s1% más de daño.'),
(7003023, 'esES', 'Enfocar fuego', 'Consume todas las acumulaciones de Frenesí de tu mascota, lo que aumenta un $s1% tu velocidad de ataque a distancia y le otorga a tu mascota $s2 p. de enfoque por acumulación. Dura $d. Tu mascota obtiene Frenesí cada vez que realiza un ataque básico.'),
(7003024, 'esES', 'Furia de raptor', 'Golpe de raptor aumenta un 10% el daño que infligen Golpe de raptor y Mordedura de mangosta. El efecto se acumula. Las aplicaciones posteriores no prolongan su duración.'),
(7003025, 'esES', 'T.N.T.', 'Aumenta un 9% el daño de Disparo explosivo y de todas tus trampas dañinas. Además, el daño inicial de Trampa explosiva y el daño periódico total de Trampa de inmolación aumentan un 25% de tu poder de ataque cuerpo a cuerpo o a distancia.'),
(7003026, 'esES', 'Ataque fugaz', 'Tras usar Golpe de raptor, obtienes un 100% más de velocidad de movimiento durante el efecto. Las facultades dañinas de tu mascota provocan un frenesí rabioso en el objetivo, que aumenta su poder de ataque cuerpo a cuerpo en 14 p. y reduce su armadura en 50 p. durante el efecto. Los enemigos rabiosos no huirán e ignorarán los efectos de miedo y horror.'),
(7003027, 'esES', 'Salva mejorada', 'Reduce un 50% el coste de maná de Salva y un 100% su tiempo de reutilización, aumenta un 100% su daño y evita que los ataques que infligen daño retrasen el lanzamiento. Salva también inflige un 3% de tu poder de ataque a distancia como daño adicional cada vez que inflige daño.'),
(7003028, 'esES', 'Ingenio', 'Reduce un 100% el coste de maná de tus trampas y un 40% sus tiempos de reutilización.'),
(7007003, 'esES', 'Ráfaga de lava', 'Lanzas al objetivo lava fundida que inflige entre ${$m1/100*$<damagepower>} y ${$M1/100*$<damagepower>} p. de daño de Fuego. Si el objetivo tiene tu Choque de llamas, Ráfaga de lava asestará un golpe crítico.'),
(7007004, 'esES', 'Mareas vivas', 'Sana a un objetivo amistoso de ${$m1/100*$<healpower>} p. a ${$M1/100*$<healpower>} p. y luego ${5*$m2/100*$<healpower>} p. más durante $d. Tu Sanación en cadena lanzada a ese objetivo principal en menos de $d aumentará un $s3% el efecto de Sanación en cadena. Este hechizo también activa Despertar ancestral.'),
(7007005, 'esES', 'Espíritu feral', 'Invoca dos espíritus de lobo a las órdenes del chamán. Duran $d.'),
(7007006, 'esES', 'Arma vorágine', 'Cuando infliges daño con un arma cuerpo a cuerpo, existe la posibilidad de que se reduzcan un $408505s1% el tiempo de lanzamiento y el coste de maná de tu siguiente hechizo de Descarga de relámpagos, Cadena de relámpagos, Ola de sanación inferior o Ráfaga de lava. La probabilidad aumenta un $s2% mientras el arma de la mano derecha esté encantada con Arma Viento furioso y un $s2% más si empuñas un arma a dos manos. Se acumula hasta $s3 veces. Dura $408505d.'),
(7007007, 'esES', 'Maremotos', 'Cuando lanzas Sanación en cadena o Mareas vivas, obtienes $s1 cargas de Maremotos, lo que reduce un $432041s1% el tiempo de lanzamiento de tu Ola de sanación, reduce un $432041s3% el tiempo de lanzamiento de tu Sanación en cadena y aumenta un $432041s2% la probabilidad de crítico de tu Ola de sanación inferior.'),
(7007008, 'esES', 'Despertar ancestral', 'Cuando realizas sanación crítica con tu Ola de sanación u Ola de sanación inferior, invocas a un espíritu ancestral para que te ayude, lo que sana instantáneamente al objetivo de tu grupo con el porcentaje de salud más bajo en un radio de 40 m un $s1% de la cantidad de sanación realizada.'),
(7007009, 'esES', 'Especialización en doble empuñadura', 'Aumenta un $s1% tu probabilidad de golpear con hechizos y ataques cuerpo a cuerpo con doble empuñadura, y tu Golpe de tormenta ahora golpea con ambas armas. Además, aumenta un $s3% el daño infligido con el arma de mano izquierda.'),
(7007010, 'esES', 'Sobrecarga', 'Otorga a tus hechizos Descarga de relámpagos, Cadena de relámpagos, Sanación en cadena, Ola de sanación y Ráfaga de lava un $h% de probabilidad de lanzar un segundo hechizo similar sobre el mismo objetivo sin coste extra, que inflige la mitad de daño o sanación y no genera amenaza.'),
(7007011, 'esES', 'Maestría con escudos', 'Cada vez que bloqueas, regeneras un 8% de tu maná máximo y obtienes armadura equivalente al 30% del valor de armadura de tu escudo. Se acumula hasta 5 veces durante 15 s. También aumentas un 10% la probabilidad de bloqueo y un 15% el valor de bloqueo. Cada vez que lanzas una facultad de Choque, obtienes 4 p. de daño con hechizos por cada punto de Defensa por encima de 5 veces tu nivel. Dura 15 s.'),
(7007012, 'esES', 'Maestría con arma a dos manos', 'Cada vez que golpeas a un enemigo con un arma a dos manos, obtienes un 45% de velocidad de ataque con armas a dos manos, un 10% más de poder de ataque y un 10% más de probabilidades de golpear con hechizos durante 10 s. Este efecto se pierde si golpeas a un enemigo con un arma de una mano.'),
(7007013, 'esES', 'Lluvia de sanación', 'Selecciona un área de 15 m alrededor del jugador seleccionado y sana a los miembros de su grupo que estén en su interior cada segundo.'),
(7007014, 'esES', 'Guía ancestral', 'Durante los siguientes $d, un $s1% de tu daño se convertirá en sanación y sanará a un máximo de 3 miembros cercanos del grupo. Además, se infligirá como daño un $s2% de tu sanación al objetivo más reciente de tu Choque de llamas.'),
(7007015, 'esES', 'Lobo fantasmal superior', 'Ahora puedes usar la facultad Lobo fantasmal dentro de un lugar. Además, reduce un 10% todo el daño que sufres mientras está activa.'),
(7007016, 'esES', 'Camino de la tierra', 'Cuando Arma Muerdepiedras está activa en el arma de la mano principal y tienes un escudo equipado, generas un 65% más de amenaza, obtienes un 25% más de salud, recibes un 10% menos de daño y reduces un 6% la probabilidad de recibir golpes críticos por ataques cuerpo a cuerpo. Choque de tierra provoca a los objetivos para que te ataquen, tiene una reutilización independiente del resto de los hechizos de choque y su alcance se reduce al cuerpo a cuerpo. El alcance de Descarga de relámpagos, Cadena de relámpagos, Sanación en cadena, Ola de sanación y Ráfaga de lava se reduce 20 m.'),
(7007017, 'esES', 'Explosión de arrabio', 'Golpea a un máximo de $i enemigos que se encuentran en un cono frente a ti, que reciben de ${$<damagepower>*$m1/100+$m2/100*$AP} a ${$<damagepower>*$M1/100+$m2/100*$AP} p. de daño de Fuego. Esta facultad genera una gran cantidad de amenaza. El daño periódico de Choque de llamas tiene un 10% de probabilidades de restablecer el tiempo de reutilización de Explosión de arrabio.'),
(7007018, 'esES', 'Oleada de poder', 'Cada vez que Choque de llamas inflige daño, hay un $h% de probabilidades de que se restablezca el tiempo de reutilización de Ráfaga de lava y Cadena de relámpagos, y de que tu siguiente lanzamiento de Ráfaga de lava o Cadena de relámpagos en $415105d sea instantáneo. Cada vez que Mareas Vivas sana, tiene un $h% de probabilidad de provocar que tu siguiente Sanación en cadena en $468526d sea instantánea. Además, obtienes una cantidad de maná equivalente a un $s2% de tu intelecto cada $440285t s.'),
(7007019, 'esES', 'Tótem señuelo', 'Invoca un tótem señuelo con $s1 p. de salud durante $d a los pies del objetivo que redirigirá a sí mismo el siguiente ataque cuerpo a cuerpo o a distancia realizado contra el objetivo. El tótem también otorga al objetivo inmunidad a los efectos de reducción de movimiento durante $436391d.'),
(7007020, 'esES', 'Espíritu del alfa', 'Imbuye al objetivo del espíritu de un lobo alfa, lo que aumenta un $s1% toda la amenaza que genera durante $d. Afecta a 1 objetivo como máximo. Si se lanza sobre otro objetivo, el chamán obtiene Beta leal, que aumenta un $443320s1% el daño físico infligido y reduce un $443320s2% toda la amenaza generada durante $d. Un objetivo no puede contar con Espíritu del alfa y Beta leal a la vez.'),
(7007021, 'esES', 'Quemar', 'Ahora, tu Choque de llamas golpea a un máximo de $s1 objetivos, su duración aumenta ${$m5/1000} s e inflige un $s3% más de daño. Además, si tienes la facultad Arma Lengua de Fuego imbuida en el arma que llevas equipada en la mano principal, obtienes un aumento al daño con hechizos equivalente a un $s7% de tu intelecto.'),
(7007022, 'esES', 'Maña mental', 'Al infligir daño con Golpe de tormenta, aumentas tu poder de ataque el equivalente a un $s1% de tu intelecto, y tu daño con hechizos el equivalente a un $s2% de tu poder de ataque total durante $415144d.'),
(7007023, 'esES', 'Sobrecargado', 'Tu Escudo de relámpagos nunca pierde cargas, tiene 3 s de tiempo de reutilización e inflige daño a los enemigos en un radio de 8 yardas.'),
(7007024, 'esES', 'Trueno ondulante', 'Descarga de relámpagos y Cadena de relámpagos tienen un 50% de probabilidades de añadir una carga a tu Escudo de relámpagos activo, hasta un máximo de 9. Choque de tierra libera las cargas por encima de 3, inflige su daño al objetivo y restaura un 2% de tu maná máximo por carga liberada.'),
(7007025, 'esES', 'Choque estático', 'Tu Escudo de relámpagos obtiene 6 cargas adicionales. Tus ataques cuerpo a cuerpo tienen un 12% de probabilidades, o un 6% si empuñas dos armas, de activar una carga e infligir daño al objetivo.'),
(7007026, 'esES', 'Coherencia', 'Sanación en cadena pierde solo un 35% de efectividad por salto y Cadena de relámpagos solo un 20%. Cada hechizo salta a un objetivo adicional.'),
(7007027, 'esES', 'Tormenta, Tierra y Fuego', 'Reduce un 25% el tiempo de reutilización de Cadena de relámpagos, hace que Tótem Nexo Terrestre enraíce a los objetivos durante 5 s al lanzarse y aumenta un 60% el daño periódico de Choque de llamas.'),
(7008004, 'esES', 'Aflicción inestable', 'La energía de las Sombras destruye lentamente al objetivo e inflige daño durante 18 s. Si se disipa, inflige daño y silencia a quien la disipe.'),
(7008005, 'esES', 'Invocar guardia vil', 'Invoca a un guardia vil que queda bajo tu control y se beneficia de los talentos y efectos que afectan a tus otros demonios.'),
(7008006, 'esES', 'Metamorfosis', 'Te transformas en demonio y aumentas tu armadura y amenaza. Esta forma de tanque modifica algunas facultades de brujo.'),
(7008007, 'esES', 'Incinerar', 'Abrasa al enemigo y aumenta un 40% todo el daño de Fuego que infliges durante 15 s.'),
(7008008, 'esES', 'Llama de las Sombras', 'Abrasa al enemigo con llamas sombrías e inflige daño periódico adicional.'),
(7008014, 'esES', 'Succión de alma', 'Hace que Drenar alma inflija daño 3 veces más rápido y aumenta lo drenado por Drenar vida y Drenar alma un 6% adicional por cada efecto de las Sombras tuyo que sufra el objetivo, hasta un máximo del 18% adicional. Además, Drenar alma ahora puede activar tu talento Ocaso.'),
(7008015, 'esES', 'Sombras y llamas', 'Tus golpes críticos con hechizos de Fuego y de las Sombras aumentan el daño de Fuego y de las Sombras que infliges un $426311s1% durante $426311d.'),
(7008016, 'esES', 'Lago de fuego', 'Lluvia de fuego ya no se canaliza, pero gana 8 s de tiempo de reutilización.'),
(7008017, 'esES', 'Maestro canalizador', 'Drenar vida ya no se canaliza, cuesta un 100% más de maná y te sana un 50% más cada vez que inflige daño.'),
(7008018, 'esES', 'Salva de descarga de las Sombras', 'Tu Descarga de las Sombras ahora golpea hasta $s1 objetivos dentro de una distancia de cadena de 10 metros, pero inflige un $s3% menos de daño.'),
(7008019, 'esES', 'Gracia demoníaca', 'Te sobrecarga de energía vil, lo que aumenta tu probabilidad de esquivar y la de tu mascota un $s1%, y tu probabilidad de asestar golpes críticos con todos tus ataques un $s2%. Dura $d.'),
(7008020, 'esES', 'Invocación', 'Si aplicas Corrupción, Inmolar, Maldición de agonía, Aflicción inestable, Llama de las Sombras o Succionar vida, infligirás al objetivo una cantidad de daño instantáneo equivalente a un pulso del daño periódico del hechizo. Si reinicias cualquiera de esos hechizos cuando les queden menos de $s1 s de duración, infligirás al objetivo una cantidad de daño instantáneo equivalente al daño periódico restante de ese hechizo.'),
(7008021, 'esES', 'Danza de los malditos', 'Tu mascota demoníaca y tú aumentáis vuestra probabilidad de esquivar el equivalente a un $s1% de tu probabilidad de golpe crítico con hechizos cada vez que asestáis un golpe crítico a un enemigo y también recuperáis un $412800s2% del maná máximo.'),
(7008022, 'esES', 'Venganza', 'Cuando se activa, esta facultad aumenta un $s1% tu salud máxima durante $d. Perderás la salud cuando se acabe el efecto. Además, Metamorfosis hace que tus alas ralenticen tu velocidad de caída.'),
(7008023, 'esES', 'Aura de Inmolación', 'Quema a los enemigos cercanos. Inflige ${$<power>*$427725m1/100} p. de daño cada vez que un enemigo te ataca cuerpo a cuerpo (no más de una vez cada segundo), reduce un $s2% todo el daño mágico que recibes y aumenta un $s3% el daño mágico que infliges. Dura $d.'),
(7008024, 'esES', 'Armadura infernal', 'Tu espíritu se imbuye de energía demoníaca, lo que reduce todo el daño mágico que recibes un porcentaje equivalente a un $s2% de tu reducción de daño físico por la armadura. Dura $d.'),
(7008025, 'esES', 'Marca de caos', 'Ahora, todas tus maldiciones, excepto Maldición de las Sombras y Maldición de los Elementos, aplican Marca de caos, lo que reduce las resistencias del objetivo a magia Arcana, Fuego, Escarcha, Naturaleza y Sombras y aumenta el daño con hechizos recibido de esas escuelas mientras dura la maldición.'),
(7008026, 'esES', 'Pandemia', 'Ahora, el daño periódico de tus facultades Corrupción, Aflicción inestable, Maldición de Agonía, Inmolar, Maldición del Apocalipsis y Succionar vida puede convertirse en golpes críticos.'),
(7008027, 'esES', 'Grimorio de sinergia', 'El daño que infligen el brujo o su demonio invocado tiene un 6% de probabilidades de aumentar un $426303s1% el infligido por el otro durante $426303d.'),
(7009003, 'esES', 'Lacerar', ''),
(7009004, 'esES', 'Rugido salvaje', ''),
(7009005, 'esES', 'Rabia', ''),
(7009006, 'esES', 'Instintos de supervivencia', ''),
(7009015, 'esES', 'Semilla viviente', 'Tus sanaciones críticas plantan una Semilla viviente en el objetivo. Florece cuando el objetivo recibe el siguiente ataque.'),
(7009016, 'esES', 'Vientos galernos', 'Aumenta un 20% el daño de Huracán, elimina su tiempo de reutilización y reduce un 30% su coste de maná.'),
(7009017, 'esES', 'Fuego solar', 'Quema al enemigo e inflige daño de Naturaleza y después inflige daño de Naturaleza adicional durante 12 s.'),
(7009018, 'esES', 'Furia de Tempestira', 'Reduce un 100% el coste de maná de Cólera. Cada vez que Cólera inflige daño, tienes un 12% de probabilidad de que tu siguiente Toque curativo se lance al instante y pueda lanzarse en cualquier forma durante 15 s.'),
(7009019, 'esES', 'Estado onírico', 'Los golpes críticos de tus hechizos dañinos no periódicos o cualquier daño de Oleada de estrellas te otorgan un 50% de tu regeneración de maná mientras lanzas hechizos durante 8 s y aumentan un 20% el daño Arcano y de Naturaleza infligido a objetivos que no sean jugadores durante 12 s.'),
(7009020, 'esES', 'Árbol de la vida', 'Aumenta un 10% la sanación recibida por los miembros del grupo en un radio de 45 m y un 60% la sanación de Crecimiento salvaje. Reduce un 20% el coste de maná de tus sanaciones periódicas, aumenta un 25% tu Espíritu y un 200% tu armadura.'),
(7009021, 'esES', 'Oleada de estrellas', 'Lanzas una oleada de energías estelares que inflige daño Arcano. Hechizo instantáneo, sin coste de maná y con 6 s de reutilización.'),
(7009022, 'esES', 'Floración', 'Alivio presto también crea una zona de Floración que sana a los miembros del grupo cercanos cada segundo durante 15 s.'),
(7009023, 'esES', 'Fuegos de Elune', 'Fuego estelar extiende Fuego lunar 6 s, Cólera extiende Fuego solar 3 s, Recrecimiento extiende Rejuvenecimiento 6 s y Triturar extiende Destripar 2 s. Cada efecto conserva su duración inicial máxima.'),
(7009024, 'esES', 'Eclipse', 'Fuego estelar y Cólera otorgan hasta 4 acumulaciones de Eclipse: un 30% de probabilidad de crítico, 1 s menos de tiempo de lanzamiento y un 70% menos de retroceso. Duración aproximada: 15 s.'),
(7009025, 'esES', 'Lluvia de estrellas', 'Inflige daño Arcano de área cada segundo durante 10 s. Cuesta un 39% del maná base y tiene 90 s de reutilización.'),
(7009026, 'esES', 'Flor de vida', 'Sana al objetivo durante $d. Al terminar Flor de vida o disiparse, vuelve a sanarlo y el druida recupera la mitad del coste de maná. Se acumula hasta $u veces.'),
(7009027, 'esES', 'Nutrir', 'Sana a un objetivo amistoso. La sanación aumenta un 20% si tiene Rejuvenecimiento, Recrecimiento, Flor de vida o Crecimiento salvaje. Se beneficia de los efectos de Toque de sanación y Recrecimiento y también los activa.');
